CREATE TABLE IF NOT EXISTS public.support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users NOT NULL, ticket_id uuid UNIQUE NOT NULL, status text DEFAULT 'open' NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, read_at timestamp with time zone); CREATE TABLE IF NOT EXISTS public.support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid REFERENCES public.support_tickets ON DELETE CASCADE NOT NULL, message text NOT NULL, is_staff boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, user_id uuid REFERENCES auth.users); CREATE OR REPLACE FUNCTION public.open_support_chat() RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS \$\\$ SELECT jsonb_build_object('ticket_id', gen_random_uuid(), 'status', 'open', 'created_at', now()) \$\\$; CREATE OR REPLACE FUNCTION public.ensure_support_ticket() RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS \$\\$ SELECT jsonb_build_object('ticket_id', coalesce((select ticket_id from support_tickets where user_id = auth.uid() order by created_at desc limit 1), gen_random_uuid()), 'status', 'open') \$\\$; CREATE OR REPLACE FUNCTION public.get_public_branding() RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS \$\\$ SELECT jsonb_build_object('name', COALESCE(app_name, 'TrendUp'), 'live_chat_welcome', COALESCE(live_chat_welcome, 'Hello {name}! 👋 Welcome to support. How can we help you today?')) FROM public.app_settings LIMIT 1; \$\\$; GRANT EXECUTE ON FUNCTION public.open_support_chat() TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.ensure_support_ticket() TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_public_branding() TO anon, authenticated; GRANT ALL ON public.support_tickets TO anon, authenticated; GRANT ALL ON public.support_messages TO anon, authenticated;
